"""Derive SkyyPets/build_skyypets_0.4.29.py from SkyyPets 0.4.28 (SkyyPets/build_skyypets_0.4.28.py = the SET pin, itself GENERATED by
tools/pets_0_4_28_patch.py - never edit a generated script, edit this patch). Every anchor is asserted once; at the end every change is
undone on a copy and compared with 0.4.28 (tools/soundpass_gen.Patch). Line endings kept.
Run:  python tools/pets_0_4_29_patch.py   then   python SkyyPets/build_skyypets_0.4.29.py   (never --deploy)
      then  python SkyyPets/test_skyypets_0.4.29.py
"""
import os, sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "tools"))
import soundpass_gen as G

NOTE = '''0.4.29 (2026-11-24, round oldmenu2) = THE PETS TAB GETS THE LAST TWO THINGS OF THE OLD PETS PAGE (SkyyMenu 0.3.70 F2). Skyy 2026-11-22
  (docs/answered/ui.md, LOCKED 'RETIRE THE OLD MENU'): "when everything is in the new system id like to disable the old menu compleatly, so instead
  of adding things like the full tree button, just build it all into the new system and remove the old "Full tree""; 2026-11-23 "looks better. go
  head and build everything on your list." No new rule, cost, number or saved line: both ops call the SAME doors the Pets page uses.
  1. THE FIRST-PET CHOICE: while a profile waits for its starter choice (PetOps.starterPending: pets.starter.choose on), pets:fn:tab adds one line per
     starter type: st|i|type|pet name|its Common portrait id|perk words ("Up to ... at Lv 50")|1 = this kind is on (0 = the old page's refusal).
     pets:fn:tabact op "start" (arg = the type 0-3) = the old page's "pick": the first press asks (PetOps.pickAsk), the SAME press again within
     15 s chooses (PetOps.chooseStarter -> PetSnd.slotDone, the page's own path); a profile that already chose = "=You already have your first pet."
  2. EGG FUSING (the Pets page's Eggs > "Fuse eggs"): op "efuse" (arg = the egg id) = the page's eggClick mode 1: the ask (PetHatchery.efuseAsk), the
     same egg with the same inventory count within 15 s fuses (PetHatchery.efuse: its own gate, click guard, counted take + give, put back on a
     short step). Not a pet egg = refused; no inventory = refused, nothing moves.
  Both are two-press ops like fuse / reb / take (another op cancels; the screen's first read clears an ask). The 350 ms same-op guard and the
  profile token rule cover them (act() checks those first). No class, system, command, setting, lang key or saved data.
  ROLLBACK: 0.4.29 -> 0.4.28 alone is safe (nothing saved; SkyyMenu 0.3.70's Pets tab then says the first-pet choice / egg fusing is not here
  - "-Unknown pet action." - and the player chooses on /pets).
'''

P = G.Patch(os.path.join(ROOT, "SkyyPets", "build_skyypets_0.4.28.py"), os.path.join(ROOT, "SkyyPets", "build_skyypets_0.4.29.py"))
if "--out" in sys.argv:
    P.dst = os.path.abspath(sys.argv[sys.argv.index("--out") + 1])
assert P.has('VERSION = "0.4.28"') and P.has("PetTabFn") and not P.has('"start".equals(op)'), "not the generated SkyyPets 0.4.28 script"
REG0, SYS0, CLS0 = P.s.count("registerCommand("), P.s.count("registerSystem("), P.s.count("= cls(")

P.rep('''"""SkyyPets 0.4.28 - build script (javassist via jpype, tools/skyybuild.py). GENERATED by tools/pets_0_4_28_patch.py from SkyyPets 0.4.27
(build_skyypets_0.4.27.py, the SET pin, itself generated by tools/pets_0_4_27_patch.py) - edit the patch, never this file.
Owner: Skyy (they/them). Run:  python SkyyPets/build_skyypets_0.4.28.py   -> SkyyPets/SkyyPets-0.4.28.jar
(no --deploy on purpose: tools/deploy_set.py installs the set once the round is ready). Test: python SkyyPets/test_skyypets_0.4.28.py

''', '''"""SkyyPets 0.4.29 - build script (javassist via jpype, tools/skyybuild.py). GENERATED by tools/pets_0_4_29_patch.py from SkyyPets 0.4.28
(build_skyypets_0.4.28.py, the SET pin, itself generated by tools/pets_0_4_28_patch.py) - edit the patch, never this file.
Owner: Skyy (they/them). Run:  python SkyyPets/build_skyypets_0.4.29.py   -> SkyyPets/SkyyPets-0.4.29.jar
(no --deploy on purpose: tools/deploy_set.py installs the set once the round is ready). Test: python SkyyPets/test_skyypets_0.4.29.py

''' + NOTE + '''
SkyyPets 0.4.28 (generated by tools/pets_0_4_28_patch.py from 0.4.27) - everything below is still true unless 0.4.29 above says otherwise:

''')
P.rep('VERSION = "0.4.28"\n', 'VERSION = "0.4.29"\n')

# ---- 1. the read: the starter choice lines (only while the profile waits for its choice)
P.rep('''     .append('|').append(f(@PKG@.PetHatchery.slotSub(ln, now, u)));
  }
  return o.toString();
}""")''', '''     .append('|').append(f(@PKG@.PetHatchery.slotSub(ln, now, u)));
  }
  if (!bad && @PKG@.PetOps.starterPending(r)) {   // 0.4.29 (oldmenu2): the first-pet choice = the old page's starter view, one line per type
    for (int i = 0; i < @PKG@.PetOps.START_TYPES.length; i++) {
      String sk = @PKG@.PetOps.starterKind(i);
      @PKG@.PetKind pk = @PKG@.PetsCfg.kind(sk);
      boolean on = pk != null && @PKG@.PetsCfg.kindOn(pk.id) && !@PKG@.PetDragon.isDragon(pk.id);
      String ic = pk == null ? null : @PKG@.PetEggDefs.portraitR(pk.id, 1);
      o.append("\\nst|").append(i).append('|').append(f(@PKG@.PetOps.START_TYPES[i])).append('|').append(f(pk == null ? sk : pk.name)).append('|')
       .append(f(ic == null ? "" : ic)).append('|').append(f(pk == null ? "" : @PKG@.PetOps.perkWords(pk))).append('|').append(on ? 1 : 0);
    }
  }
  return o.toString();
}""")''')

# ---- 2. the act: start + efuse are two-press ops (never cleared by their own press)
P.rep('''  if (!"fuse".equals(op) && !"reb".equals(op) && !"take".equals(op)) CONF.remove(u);''',
      '''  if (!"fuse".equals(op) && !"reb".equals(op) && !"take".equals(op) && !"start".equals(op) && !"efuse".equals(op)) CONF.remove(u);   // 0.4.29: + start, efuse''')
P.rep('''  if ("ride".equals(op)) return @PKG@.PetRideFn.ride(u, @PKG@.PetRide.now());
  long cm = -1L;''', '''  if ("start".equals(op)) {   // 0.4.29 (oldmenu2): the old Pets page's starter "pick" - ask, then the same type again chooses
    int si = num(a, -1);
    if (!@PKG@.PetOps.starterPending(r)) { CONF.remove(u); return "=You already have your first pet."; }
    String c = "start|" + si;
    if (confirmed(u, c)) return @PKG@.PetSnd.slotDone(u, @PKG@.PetOps.chooseStarter(u, si, who), true);
    return ask(u, c, @PKG@.PetOps.pickAsk(si));
  }
  if ("efuse".equals(op)) {   // 0.4.29 (oldmenu2): the old Pets page's Eggs > Fuse eggs (eggClick mode 1) - ask, then the same egg + count fuses
    if (inv == null) { CONF.remove(u); return "-Your inventory could not be read - nothing moved."; }
    if (a.length() == 0 || @PKG@.PetEggDefs.index(a) < 0) { CONF.remove(u); return "-That is not a pet egg."; }
    String c = "efuse|" + a + "|" + inv.count(a);
    if (confirmed(u, c)) return @PKG@.PetHatchery.efuse(u, inv, a, who);
    return ask(u, c, @PKG@.PetHatchery.efuseAsk(u, inv, a));
  }
  if ("ride".equals(op)) return @PKG@.PetRideFn.ride(u, @PKG@.PetRide.now());
  long cm = -1L;''')

assert P.s.count("registerCommand(") == REG0 and P.s.count("registerSystem(") == SYS0 and P.s.count("= cls(") == CLS0, "0.4.29: no class, system or command"
P.finish()
